using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEditor;using Newtonsoft.Json;
public static class PlayC01 {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/검수/2026-11-07_C01_InstrumentDetail/";
 static double start;static int firstFrame,lastFrame;static GameObject player;static Vector3 from;static Keyboard keyboard;static bool released,keyboardWasEnabled;static string label;static List<float> frameTimes=new List<float>();static List<object> errors=new List<object>();static InputSettings.BackgroundBehavior background;
 public static object Inside()=>Start("inside",new Vector3(-9.3f,-81.32f,-10f),0);
 public static object Tunnel()=>Start("tunnel",new Vector3(-65f,-81.32f,-20.76f),77.85f);
 static object Start(string id,Vector3 p,float yaw){if(!Application.isPlaying)throw new Exception("Play mode required");label=id;frameTimes.Clear();errors.Clear();player=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.transform.SetPositionAndRotation(p,Quaternion.Euler(0,yaw,0));cc.enabled=true;Physics.SyncTransforms();from=p;firstFrame=lastFrame=Time.frameCount;start=EditorApplication.timeSinceStartup;released=false;
 background=InputSystem.settings.backgroundBehavior;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;keyboard=Keyboard.current;if(keyboard==null)throw new Exception("No current keyboard");keyboardWasEnabled=keyboard.enabled;if(!keyboardWasEnabled)InputSystem.EnableDevice(keyboard);InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.W));Application.logMessageReceived+=Log;EditorApplication.update+=Tick;return new{id,frame=firstFrame,from=from.ToString()};}
 static void Log(string m,string st,LogType t){if(t==LogType.Error||t==LogType.Exception||t==LogType.Warning)errors.Add(new{message=m,type=t.ToString()});}
 static void Tick(){if(!Application.isPlaying){End(false);return;}EditorApplication.QueuePlayerLoopUpdate();double elapsed=EditorApplication.timeSinceStartup-start;if(Time.frameCount!=lastFrame){lastFrame=Time.frameCount;if(elapsed>.9)frameTimes.Add(Time.unscaledDeltaTime*1000);}
 if(elapsed<.50)InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.W));if(!released&&elapsed>.50){InputSystem.QueueStateEvent(keyboard,new KeyboardState());released=true;}
 if(elapsed>5.0)End(true);}
 static void End(bool complete){EditorApplication.update-=Tick;Application.logMessageReceived-=Log;if(keyboard!=null)InputSystem.QueueStateEvent(keyboard,new KeyboardState());if(keyboard!=null&&!keyboardWasEnabled)InputSystem.DisableDevice(keyboard);InputSystem.settings.backgroundBehavior=background;var sorted=frameTimes.OrderBy(x=>x).ToArray();var delta=player.transform.position-from;delta.y=0;var result=new{complete,label,firstFrame,lastFrame,framesAdvanced=lastFrame-firstFrame,start=from.ToString(),end=player.transform.position.ToString(),displacement=delta.magnitude,frames=sorted.Length,medianMs=sorted.Length>0?sorted[sorted.Length/2]:0,p95Ms=sorted.Length>0?sorted[(int)((sorted.Length-1)*.95)]:0,meanMs=sorted.Length>0?sorted.Average():0,screen=new[]{Screen.width,Screen.height},drawCalls=UnityEditor.UnityStats.drawCalls,triangles=UnityEditor.UnityStats.triangles,errors,device="Existing keyboard through Input System; W down/up; focus override restored"};File.WriteAllText(O+"play_"+label+".json",JsonConvert.SerializeObject(result,Formatting.Indented));}
}
